    pub(crate) index_status: fjall::Keyspace,
    pub(crate) index_workflow: fjall::Keyspace,
    pub(crate) index_action: fjall::Keyspace,
    pub(crate) emergency_deny: fjall::Keyspace,
    pub(crate) artifact_acceptance: fjall::Keyspace,
    #[cfg(test)]
