//! run metadata, journal events, snapshots, and blobs.
use std::path::Path;
use std::sync::Mutex;
#[cfg(test)]
use std::sync::atomic::{AtomicBool, Ordering};
use crate::{
    constants::{
        KEYSPACE_ARTIFACT_ACCEPTANCE, KEYSPACE_BLOB, KEYSPACE_COMPILED_IR, KEYSPACE_EMERGENCY_DENY,
        KEYSPACE_INDEX_ACTION, KEYSPACE_INDEX_STATUS, KEYSPACE_INDEX_WORKFLOW, KEYSPACE_RUN_EVENT,
        KEYSPACE_RUN_HEADER, KEYSPACE_RUN_INPUTS, KEYSPACE_RUN_SNAPSHOT, KEYSPACE_WORKFLOW_SOURCE,
    },
    error::JournalError,
    process_lock::ProcessLock,
    types::{FjallConfig, KeyspaceProfile},
