            .store(true, Ordering::SeqCst);
    }

    #[cfg(test)]
    pub(crate) fn consume_compiled_ir_readback_failure_for_test(&self) -> bool {
        self.fail_next_compiled_ir_readback
            .swap(false, Ordering::SeqCst)
    }

